"""Notebook ejecutable del tuning; conserva los notebooks de v1 y v2."""
from pathlib import Path
import json, sys, tempfile
import nbformat as nbf
from nbclient import NotebookClient
from jupyter_client import KernelManager
from jupyter_client.kernelspec import KernelSpecManager

ROOT=Path(__file__).resolve().parents[1]

def main():
    md,code=nbf.v4.new_markdown_cell,nbf.v4.new_code_cell
    cells=[
    md('# Ajustar el modelo y el punto de corte\n\nProyecto individual tutorado con Pablo Valenzuela. Se conservan los artefactos anteriores. Esta búsqueda nace después de haber observado 2024 en v1 y v2: su reevaluación temporal sigue siendo **exploratoria**. Mejorar un score de clasificación no equivale a demostrar certeza individual ni precisión futura.'),
    md('## 1. Objetivo y protocolo registrado\n\nSe busca mayor F1 macro con hiperparámetros y corte de clasificación elegidos usando respuestas hasta 2017. La definición de la respuesta permanece en crecimiento anual ≥1%. Se comparan 19 configuraciones de Random Forest, Logistic Regression y Gradient Boosting, con nueve cortes (0,30 a 0,70): 171 combinaciones.\n\nSe usa CV anidada: cinco particiones externas reservan comunas para evaluar el procedimiento; en cada ajuste externo, cuatro particiones internas eligen configuración y corte sin utilizar las comunas externas. Después se elige la configuración final con cinco particiones de las 314 comunas anteriores a 2024. La elección queda guardada antes de la reevaluación 2017–2024. La CV es entre comunas de una época y los datos ya participaron en versiones previas; no es una prueba temporal final nueva.\n\nPara reproducir la búsqueda completa: `.venv/bin/python experiments/tuning_crecimiento.py`. Este notebook vuelve a entrenar el candidato seleccionado y contrasta las salidas guardadas; muestra la búsqueda completa y las particiones anidadas sin ejecutar otra vez sus 475 ajustes internos.'),
    code("from pathlib import Path\nimport json,sys\nimport numpy as np\nimport pandas as pd\nimport joblib\nfrom sklearn.model_selection import StratifiedKFold,FixedThresholdClassifier\nfrom IPython.display import display,Image\nROOT=Path.cwd()\nif not (ROOT/'experiments').exists():ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'experiments'))\nimport tuning_crecimiento as t\nimport crecimiento_v2 as v2\nimport crecimiento_censal as v1\nprotocol=json.loads(t.PROTOCOL.read_text())\nclosed=json.loads((t.OUT/'seleccion_cerrada.json').read_text())\nsummary=json.loads((t.OUT/'resumen.json').read_text())\nprofiles=pd.read_csv(v2.OUT/'perfiles_censales.csv')\ncore=closed['core_codes']\nall_codes=sorted(core+v2.RECOVERED)\nprint('Configuración:',closed['candidate'])\nprint('Corte sobre score:',closed['threshold'],'; umbral de respuesta:',protocol['target_threshold_annual_growth'])\nprint('Selección usó respuestas de 2024:',closed['selection_used_2024_labels'])\nprint('2024 conocido previamente:',closed['2024_already_observed_in_prior_versions'])"),
    md('## 2. Preparación y muestra\n\nUnidad de entrenamiento: comuna-período. Los cientos de miles de residentes no son cientos de miles de ejemplos independientes: se ajusta con 314 comunas. Se conservan las proporciones de menores y mayores, población logarítmica y crecimiento anterior; algunas alternativas incluyen cambios anuales de proporciones de edad. El escalado logístico se ajusta dentro de cada partición.\n\nTemuco y Padre Las Casas permanecen como aplicaciones adicionales fuera de la selección histórica. Padre Las Casas utiliza 2002 y 2017, sin incorporar 1992. La recuperación territorial y la residencia habitual identificada mantienen las limitaciones documentadas en v2.'),
    code("history=profiles.query('year<=2017').copy()\n_,X,_=v2.inputs(history,1992,2002,core)\ny=np.asarray(v2.labels(history,2002,2017,core)[0])\nassert len(X)==314 and set(history.year)=={1992,2002,2017}\ndisplay(X.describe().T)\nprint('Clases:',np.bincount(y))"),
    md('## 3. Evaluación externa del procedimiento de ajuste\n\nLas métricas externas se calculan con modelos y cortes elegidos en cada parte interna. Pueden diferir de la métrica usada para escoger el modelo final. El Random Forest v2 fijo y la continuidad previa se comparan con las mismas comunas externas; no se presentan las mejores métricas internas como si fueran externas.'),
    code("folds=json.loads((t.OUT/'particiones_anidadas.json').read_text())\nreserved=[]\nfor fold in folds:\n    train,valid=set(fold['train']),set(fold['validation'])\n    assert not train&valid and train|valid==set(core)\n    for inner in fold['inner_folds']:\n        fit,selection=set(inner['train']),set(inner['validation'])\n        assert not fit&selection and fit|selection==train\n        assert not (fit|selection)&valid\n    reserved+=fold['validation']\nassert sorted(reserved)==sorted(core)\ndisplay(pd.DataFrame([{'partición':i+1,'candidato':f['chosen']['id'],'corte':f['threshold'],'F1 externo':f['external_metrics']['f1_macro']} for i,f in enumerate(folds)]))\ndisplay(pd.DataFrame([{'alternativa':k,'F1 macro externo':r['f1_macro'],'aciertos':round(r['accuracy']*r['n']),'n':r['n']} for k,r in summary['validation'].items() if isinstance(r,dict)]))"),
    md('## 4. Elección final y reproducción de sus scores\n\nSe muestran las 171 combinaciones registradas. La media de F1 por partición, seguida de exactitud, exactitud balanceada y simplicidad, determina la elección. El corte se busca con predicciones fuera del ajuste; no con scores calculados sobre las mismas filas usadas para entrenar. Las probabilidades originales se mantienen al cambiar el corte: cambiar etiquetas por sí solo no calibra probabilidades.'),
    code("search=pd.read_csv(t.OUT/'busqueda_final.csv')\nbest=max(search.to_dict('records'),key=t.rank)\nassert len(search)==171 and best['candidate']==closed['candidate']['id']\nassert best['threshold']==closed['threshold']\ndisplay(search.sort_values('selection_f1_mean',ascending=False).head(15))\nselected_scores=np.full(len(y),np.nan)\nfor fit,valid in StratifiedKFold(**protocol['final_selection_validation']).split(X,y):\n    fitted=t.make_model(closed['candidate']).fit(X.iloc[fit],y[fit])\n    selected_scores[valid]=fitted.predict_proba(X.iloc[valid])[:,1]\nrecorded=pd.read_csv(t.OUT/'scores_seleccion.csv')\nnp.testing.assert_allclose(selected_scores,recorded[closed['candidate']['id']])\nprint('Scores de selección reproducidos sin etiquetas de 2024.')"),
    md('## 5. Reevaluación temporal exploratoria de 2024\n\nSe mantiene el denominador de 314 comunas para comparar con v2 y continuidad. También se muestra el ajuste del corte del Random Forest v2 como comparación predefinida: su corte se eligió antes de consultar 2024. No se ajustan parámetros después de esta reevaluación. Se informan falsas alertas y casos de crecimiento alto omitidos, además de aciertos y F1.'),
    code("historical=FixedThresholdClassifier(t.make_model(closed['candidate']),threshold=closed['threshold'],response_method='predict_proba').fit(X,y)\ninitial,X_test,old=v2.inputs(profiles,2002,2017,all_codes)\ny_test=np.asarray(v2.labels(profiles,2017,2024,all_codes)[0])\nsaved=joblib.load(t.OUT/'clasificador_historico.joblib')\nnp.testing.assert_allclose(historical.predict_proba(X_test),saved.predict_proba(X_test))\nnp.testing.assert_array_equal(historical.predict(X_test),saved.predict(X_test))\ndisplay(pd.DataFrame([{'alternativa':k,'F1 macro':r['f1_macro'],'aciertos':round(r['accuracy']*r['n']),'n':r['n'],'falsas alertas':r['confusion'][0][1],'omitidos':r['confusion'][1][0]} for k,r in summary['test'].items()]))\ndisplay(pd.DataFrame(summary['test']['tuneado']['confusion'],index=['Real <1%','Real ≥1%'],columns=['Predice <1%','Predice ≥1%']))\ndisplay(pd.DataFrame(summary['test']['tuneado']['classes']).T)\nprint('Comparación pareada con tendencia:',summary['paired_vs_persistence'])\ndisplay(Image(filename=str(t.OUT/'evaluacion.png')))\nindividual=pd.read_csv(t.OUT/'predicciones_historicas.csv')\ndisplay(individual.loc[individual.code.isin(v2.RECOVERED),['name','previous_rate','score','score_threshold','predicted_class','actual_class','actual_rate','correct']])"),
    md('## 6. Ajuste separado para 2031\n\nEl escenario futuro utiliza otro modelo, ajustado con 630 ejemplos y respuestas conocidas hasta 2024. Se conserva la configuración y corte seleccionados con la etapa anterior. El score es una salida sin calibrar; no se etiqueta como porcentaje de certeza. No existe resultado observado de 2031 para comprobarlo. El cambio de época, de duraciones y de proporción de clases sigue limitando la transferencia.'),
    code("future=FixedThresholdClassifier(t.make_model(closed['candidate']),threshold=closed['threshold'],response_method='predict_proba').fit(pd.concat([X,X_test]),np.concatenate([y,y_test]))\n_,X_future,_=v2.inputs(profiles,2017,2024,all_codes)\nsaved_future=joblib.load(t.OUT/'clasificador_futuro.joblib')\nnp.testing.assert_allclose(future.predict_proba(X_future),saved_future.predict_proba(X_future))\nrecords=json.loads((t.OUT/'modelo.json').read_text())['records']\nassert all(r['forecast']['verified']==False and 'actual_class' not in r['forecast'] for r in records)\ndisplay(pd.DataFrame([{'comuna':r['name'],'clase experimental':r['forecast']['predicted_class'],'score sin calibrar':r['forecast']['score'],'corte':r['forecast']['score_threshold']} for r in records if r['recovered']]))\nprint('Ajuste histórico: 314; ajuste futuro:',len(X)+len(X_test))"),
    md('## 7. Interpretación y fuentes\n\nUna mejora de exactitud sobre 2024 no demuestra automáticamente precisión futura. La selección se hace con datos previos, pero el diseño del experimento ya conoce los resultados de versiones anteriores. Más parámetros tampoco añaden épocas ni muestras independientes. Si el tuning no mejora, se conserva ese resultado negativo; no se continúa buscando sobre 2024 hasta obtener una cifra mayor.\n\nFuentes: [Censos del INE](https://www.ine.gob.cl/estadisticas-por-tema/demografia-y-poblacion/censo-de-poblacion-y-vivienda). Misma preparación, exclusiones y atribución INE CC BY-SA 4.0 de v2; fuentes exactas y hashes en `data/raw/ine/crecimiento`. Método: [ajuste de cortes de scikit-learn 1.7](https://scikit-learn.org/1.7/modules/classification_threshold.html) y [validación cruzada](https://scikit-learn.org/1.7/modules/cross_validation.html).\n\nLa tasa anual que define la clase y el corte sobre el score del modelo son diferentes. Un score alto sin calibración no garantiza una probabilidad correcta para una comuna. No se presenta el escenario como una proyección oficial.')
    ]
    notebook=nbf.v4.new_notebook(cells=cells)
    notebook.metadata.kernelspec={'display_name':'Python 3','name':'python3','language':'python'}
    notebook.metadata.language_info={'name':'python','version':sys.version.split()[0]}
    with tempfile.TemporaryDirectory() as directory:
        spec=Path(directory)/'censo-tuning'
        spec.mkdir()
        (spec/'kernel.json').write_text(json.dumps({'argv':[sys.executable,'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'Tuning censal','language':'python'}))
        manager=KernelSpecManager(kernel_dirs=[directory])
        client=NotebookClient(notebook,timeout=120,resources={'metadata':{'path':str(ROOT)}},kernel_name='censo-tuning')
        client.km=KernelManager(kernel_name='censo-tuning',kernel_spec_manager=manager)
        client.execute()
    nbf.validate(notebook)
    target=ROOT/'experiments/estudio_tuning_crecimiento.ipynb'
    nbf.write(notebook,target)
    print('Notebook de tuning ejecutado:',target)

if __name__=='__main__':main()
